import { useCallback, useEffect, useMemo, useState } from 'react';
import Icon from '../components/Icon.jsx';
import { EmptyState, Pill } from '../components/Shared.jsx';
import { apiRequest, downloadProtectedFile } from '../api.js';
import { exportPdf, exportXlsx } from '../utils/exporters.js';

const blankEquipment = { codigo:'', nombre:'', tipoEquipo:'Medidor de pH', fabricante:'', modelo:'', modoLectura:'MANUAL', estado:'ACTIVO', estadoConexion:'NO_APLICA', idPunto:'', idPersonalResponsable:'', ultimaRevision:'', proximaRevision:'', observaciones:'' };
const blankPerson = { nombres:'', apellidos:'', cargo:'', area:'Operaciones PTAR', turno:'07:00–15:00', telefono:'', correo:'', estado:'ACTIVO' };
const blankMaintenance = { idEquipo:'', idPersonalAsignado:'', fechaHoraProgramada:'', tipo:'Preventivo', descripcion:'', resultado:'' };
const canManage = (role) => role === 'ADMINISTRADOR' || role === 'SUPERVISOR' || role === 'GERENTE';
const fmtDate = (v) => v ? new Date(v).toLocaleString('es-PE', { dateStyle:'medium', timeStyle:'short' }) : '—';
const text = (v) => v == null || v === '' ? '—' : String(v);

export default function OperationsPanel({ isAdmin, role, notify }) {
  const [tab, setTab] = useState(isAdmin ? 'reportes' : 'enviar');
  const [equipos, setEquipos] = useState([]);
  const [personal, setPersonal] = useState([]);
  const [incidencias, setIncidencias] = useState([]);
  const [mantenimientos, setMantenimientos] = useState([]);
  const [puntos, setPuntos] = useState([]);
  const [mediciones, setMediciones] = useState([]);
  const [alertasRegistradas, setAlertasRegistradas] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [query, setQuery] = useState('');
  const [equipmentModal, setEquipmentModal] = useState(null);
  const [equipmentForm, setEquipmentForm] = useState(blankEquipment);
  const [personModal, setPersonModal] = useState(null);
  const [personForm, setPersonForm] = useState(blankPerson);
  const [maintenanceModal, setMaintenanceModal] = useState(false);
  const [maintenanceForm, setMaintenanceForm] = useState(blankMaintenance);
  const [selectedIncident, setSelectedIncident] = useState(null);
  const [incidentForm, setIncidentForm] = useState({ estado:'EN_REVISION', prioridad:'MEDIA', idEquipo:'', idPersonalAsignado:'', fechaHoraRevision:'', resultadoResolucion:'', categoria:'', titulo:'', zona:'', descripcion:'' });
  const [reportForm, setReportForm] = useState({ categoria:'Observación ambiental', titulo:'', zona:'', descripcion:'' });
  const [reportFiles, setReportFiles] = useState([]);
  const [publicFiles, setPublicFiles] = useState([]);
  const [adminPublicFiles, setAdminPublicFiles] = useState([]);
  const [publicFileForm, setPublicFileForm] = useState({ titulo:'', descripcion:'', publicado:true });
  const [publicFileUpload, setPublicFileUpload] = useState(null);
  const [editingPublicFile, setEditingPublicFile] = useState(null);
  const [attachmentTarget, setAttachmentTarget] = useState(null);
  const [incidentAttachments, setIncidentAttachments] = useState([]);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    setLoading(true); setError('');
    try {
      const inc = await apiRequest('/api/operacion/incidencias');
      setIncidencias(Array.isArray(inc) ? inc : []);
      try { const publicList = await apiRequest('/api/operacion/archivos-publicos'); setPublicFiles(Array.isArray(publicList) ? publicList : []); } catch { setPublicFiles([]); }
      if (isAdmin) { try { const allPublic = await apiRequest('/api/operacion/archivos-publicos/admin'); setAdminPublicFiles(Array.isArray(allPublic) ? allPublic : []); } catch { setAdminPublicFiles([]); } }
      if (isAdmin || canManage(role)) {
        const eq = await apiRequest('/api/operacion/equipos');
        setEquipos(Array.isArray(eq) ? eq : []);
      } else {
        setEquipos([]);
      }
      if (isAdmin) {
        const [people, maint, places, measurementResult, alertResult] = await Promise.all([
          apiRequest('/api/operacion/personal'),
          apiRequest('/api/operacion/mantenimientos'),
          apiRequest('/api/puntos-monitoreo?estado=ACTIVO'),
          apiRequest('/api/monitoreos?page=0&size=500&sort=horaMuestreo,desc'),
          apiRequest('/api/alertas?page=0&size=500'),
        ]);
        const measurementList = Array.isArray(measurementResult) ? measurementResult : (measurementResult?.content || []);
        const alertList = Array.isArray(alertResult) ? alertResult : (alertResult?.content || []);
        setPersonal(Array.isArray(people) ? people : []);
        setMantenimientos(Array.isArray(maint) ? maint : []);
        setPuntos(Array.isArray(places) ? places : []);
        setMediciones(measurementList); setAlertasRegistradas(alertList);
      } else if (canManage(role)) {
        const [maint, places] = await Promise.all([
          apiRequest('/api/operacion/mantenimientos'),
          apiRequest('/api/puntos-monitoreo?estado=ACTIVO'),
        ]);
        setMantenimientos(Array.isArray(maint) ? maint : []);
        setPuntos(Array.isArray(places) ? places : []);
      }
    } catch (e) { setError(e.message || 'No se pudo cargar el centro de alertas desde el backend.'); }
    finally { setLoading(false); }
  }, [isAdmin, role]);

  useEffect(() => { load(); }, [load]);

  const filteredEquipment = useMemo(() => equipos.filter((e) => `${e.codigo} ${e.nombre} ${e.tipoEquipo} ${e.fabricante} ${e.modelo}`.toLowerCase().includes(query.toLowerCase())), [equipos, query]);
  const filteredPeople = useMemo(() => personal.filter((p) => `${p.nombres} ${p.apellidos} ${p.cargo} ${p.area} ${p.correo}`.toLowerCase().includes(query.toLowerCase())), [personal, query]);
  const filteredIncidents = useMemo(() => incidencias.filter((r) => `${r.titulo} ${r.categoria} ${r.zona} ${r.descripcion} ${r.nombreReportante} ${r.estado}`.toLowerCase().includes(query.toLowerCase())), [incidencias, query]);

  const startEquipment = (item = null) => {
    setEquipmentModal(item || { isNew: true });
    setEquipmentForm(item ? { codigo:item.codigo || '', nombre:item.nombre || '', tipoEquipo:item.tipoEquipo || '', fabricante:item.fabricante || '', modelo:item.modelo || '', modoLectura:item.modoLectura || 'MANUAL', estado:item.estado || 'ACTIVO', estadoConexion:item.estadoConexion || 'NO_APLICA', idPunto:item.idPunto == null ? '' : String(item.idPunto), idPersonalResponsable:item.idPersonalResponsable == null ? '' : String(item.idPersonalResponsable), ultimaRevision:item.ultimaRevision || '', proximaRevision:item.proximaRevision || '', observaciones:item.observaciones || '' } : { ...blankEquipment });
  };
  const saveEquipment = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const payload = { ...equipmentForm, idPunto: equipmentForm.idPunto ? Number(equipmentForm.idPunto) : null, idPersonalResponsable: equipmentForm.idPersonalResponsable ? Number(equipmentForm.idPersonalResponsable) : null, ultimaRevision: equipmentForm.ultimaRevision || null, proximaRevision: equipmentForm.proximaRevision || null };
      await apiRequest(equipmentModal?.idEquipo ? `/api/operacion/equipos/${equipmentModal.idEquipo}` : '/api/operacion/equipos', { method:equipmentModal?.idEquipo ? 'PUT' : 'POST', body:JSON.stringify(payload) });
      notify(equipmentModal ? 'Equipo actualizado en la base de datos.' : 'Equipo registrado en la base de datos.'); setEquipmentModal(null); await load();
    } catch(e) { setError(e.message || 'No se pudo guardar el equipo.'); }
    finally { setBusy(false); }
  };
  const changeEquipmentState = async (item) => {
    const next = item.estado === 'INACTIVO' ? 'ACTIVO' : 'INACTIVO';
    if (!window.confirm(`${next === 'INACTIVO' ? 'Desactivar' : 'Activar'} el equipo ${item.codigo}? El historial se conservará.`)) return;
    try { await apiRequest(`/api/operacion/equipos/${item.idEquipo}/estado`, { method:'PATCH', body:JSON.stringify({ estado:next }) }); notify(`Equipo ${next.toLowerCase()}.`); await load(); }
    catch(e) { notify(e.message || 'No se pudo cambiar el estado del equipo.'); }
  };

  const startPerson = (item = null) => { setPersonModal(item || { isNew: true }); setPersonForm(item ? { nombres:item.nombres || '', apellidos:item.apellidos || '', cargo:item.cargo || '', area:item.area || '', turno:item.turno || '', telefono:item.telefono || '', correo:item.correo || '', estado:item.estado || 'ACTIVO' } : { ...blankPerson }); };
  const savePerson = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    try { await apiRequest(personModal?.idPersonal ? `/api/operacion/personal/${personModal.idPersonal}` : '/api/operacion/personal', { method:personModal?.idPersonal ? 'PUT' : 'POST', body:JSON.stringify(personForm) }); notify(personModal ? 'Trabajador actualizado.' : 'Trabajador registrado.'); setPersonModal(null); await load(); }
    catch(e) { setError(e.message || 'No se pudo guardar al trabajador.'); }
    finally { setBusy(false); }
  };
  const changePersonState = async (p) => {
    const next = p.estado === 'ACTIVO' ? 'INACTIVO' : 'ACTIVO';
    if (!window.confirm(`${next === 'INACTIVO' ? 'Desactivar' : 'Activar'} a ${p.nombres} ${p.apellidos}?`)) return;
    try { await apiRequest(`/api/operacion/personal/${p.idPersonal}/estado`, { method:'PATCH', body:JSON.stringify({ estado:next }) }); notify(`Trabajador ${next.toLowerCase()}.`); await load(); }
    catch(e) { notify(e.message || 'No se pudo cambiar el estado del trabajador.'); }
  };

  const submitReport = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const created = await apiRequest('/api/operacion/incidencias', { method:'POST', body:JSON.stringify({ ...reportForm, idEquipo:null }) });
      const uploadErrors = [];
      for (const file of reportFiles) {
        try {
          const data = new FormData(); data.append('archivo', file); data.append('descripcion', `Evidencia del reporte: ${reportForm.titulo.trim()}`);
          await apiRequest(`/api/operacion/incidencias/${created.idIncidencia}/adjuntos`, { method:'POST', body:data });
        } catch (uploadError) { uploadErrors.push(`${file.name}: ${uploadError.message || 'no se pudo subir'}`); }
      }
      setReportForm({ categoria:'Observación ambiental', titulo:'', zona:'', descripcion:'' }); setReportFiles([]);
      const evidencePicker = document.getElementById('incident-evidence'); if (evidencePicker) evidencePicker.value = '';
      if (uploadErrors.length) notify(`La observación se guardó, pero algunos archivos no se adjuntaron: ${uploadErrors.join('; ')}`);
      else notify(`Tu observación quedó registrada${reportFiles.length ? ` con ${reportFiles.length} archivo(s) adjunto(s)` : ''} y pendiente de revisión.`);
      setTab('mis-reportes'); await load();
    } catch(e) { setError(e.message || 'No se pudo enviar el reporte.'); }
    finally { setBusy(false); }
  };
  const viewAttachments = async (incident) => {
    setAttachmentTarget(incident); setIncidentAttachments([]); setError('');
    try { const result = await apiRequest(`/api/operacion/incidencias/${incident.idIncidencia}/adjuntos`); setIncidentAttachments(Array.isArray(result) ? result : []); }
    catch(e) { setError(e.message || 'No se pudieron consultar los archivos adjuntos.'); }
  };
  const downloadOperationFile = async (file, publicRoute = false) => {
    try { await downloadProtectedFile(publicRoute ? `/api/operacion/archivos-publicos/${file.idArchivo}/descarga` : `/api/operacion/archivos/${file.idArchivo}/descarga`, file.nombreOriginal || file.titulo || 'archivo'); }
    catch(e) { notify(e.message || 'No se pudo descargar el archivo.'); }
  };
  const uploadPublicFile = async (event) => {
    event.preventDefault(); if (!publicFileUpload) { setError('Selecciona el archivo que deseas publicar.'); return; }
    setBusy(true); setError('');
    try {
      const form = new FormData(); form.append('archivo', publicFileUpload); form.append('titulo', publicFileForm.titulo.trim());
      form.append('descripcion', publicFileForm.descripcion.trim()); form.append('publicado', String(publicFileForm.publicado));
      await apiRequest('/api/operacion/archivos-publicos', { method:'POST', body:form });
      setPublicFileForm({ titulo:'', descripcion:'', publicado:true }); setPublicFileUpload(null);
      const picker = document.getElementById('public-file-picker'); if (picker) picker.value = '';
      notify('Archivo guardado en la biblioteca.'); setTab('archivos'); await load();
    } catch(e) { setError(e.message || 'No se pudo publicar el archivo.'); }
    finally { setBusy(false); }
  };
  const savePublicFileMetadata = async (file, values) => {
    setBusy(true); setError('');
    try {
      await apiRequest(`/api/operacion/archivos-publicos/${file.idArchivo}`, { method:'PUT', body:JSON.stringify({ titulo:values.titulo, descripcion:values.descripcion, publicado:values.publicado, estado:values.estado }) });
      setEditingPublicFile(null); notify('Información del archivo actualizada.'); await load();
    } catch(e) { setError(e.message || 'No se pudo actualizar el archivo.'); }
    finally { setBusy(false); }
  };
  const publishIncidentAttachment = async (file) => {
    try { await apiRequest(`/api/operacion/archivos/${file.idArchivo}/publicacion`, { method:'PATCH', body:JSON.stringify({ publicado:!file.publicado }) }); notify(file.publicado ? 'Se quitó el archivo de la biblioteca pública.' : 'Archivo publicado para descarga pública.'); if (attachmentTarget) await viewAttachments(attachmentTarget); await load(); }
    catch(e) { setError(e.message || 'No se pudo cambiar la publicación del archivo.'); }
  };
  const startIncident = (item) => { setSelectedIncident(item); setIncidentForm({ estado:item.estado || 'EN_REVISION', prioridad:item.prioridad || 'MEDIA', idEquipo:item.idEquipo == null ? '' : String(item.idEquipo), idPersonalAsignado:item.idPersonalAsignado == null ? '' : String(item.idPersonalAsignado), fechaHoraRevision:item.fechaHoraRevision ? String(item.fechaHoraRevision).slice(0,16) : '', resultadoResolucion:item.resultadoResolucion || '', categoria:item.categoria || '', titulo:item.titulo || '', zona:item.zona || '', descripcion:item.descripcion || '' }); };
  const manageIncident = async (event) => {
    event.preventDefault(); if (!selectedIncident) return; setBusy(true); setError('');
    try {
      const payload = { ...incidentForm, idEquipo:incidentForm.idEquipo ? Number(incidentForm.idEquipo) : null, idPersonalAsignado:incidentForm.idPersonalAsignado ? Number(incidentForm.idPersonalAsignado) : null, fechaHoraRevision:incidentForm.fechaHoraRevision || null };
      await apiRequest(`/api/operacion/incidencias/${selectedIncident.idIncidencia}/gestionar`, { method:'PATCH', body:JSON.stringify(payload) });
      notify('Reporte actualizado y guardado en la base de datos.'); setSelectedIncident(null); await load();
    } catch(e) { setError(e.message || 'No se pudo gestionar el reporte.'); }
    finally { setBusy(false); }
  };

  const saveMaintenance = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const payload = { ...maintenanceForm, idEquipo:Number(maintenanceForm.idEquipo), idPersonalAsignado:Number(maintenanceForm.idPersonalAsignado), fechaHoraProgramada:maintenanceForm.fechaHoraProgramada, tipo:maintenanceForm.tipo, descripcion:maintenanceForm.descripcion, estado:'PROGRAMADO' };
      await apiRequest('/api/operacion/mantenimientos', { method:'POST', body:JSON.stringify(payload) });
      setMaintenanceModal(false); setMaintenanceForm({ ...blankMaintenance }); notify('Mantenimiento programado.'); await load();
    } catch(e) { setError(e.message || 'No se pudo programar el mantenimiento.'); }
    finally { setBusy(false); }
  };
  const setMaintenanceState = async (m, next) => {
    const resultado = next === 'COMPLETADO' ? window.prompt('Escribe el resultado de la revisión (opcional):', m.resultado || '') : m.resultado || '';
    if (resultado === null) return;
    try { await apiRequest(`/api/operacion/mantenimientos/${m.idMantenimiento}/estado`, { method:'PATCH', body:JSON.stringify({ estado:next, resultado }) }); notify('Estado de mantenimiento actualizado.'); await load(); }
    catch(e) { notify(e.message || 'No se pudo actualizar el mantenimiento.'); }
  };

  const exportOperationalData = (format) => {
    if (!isAdmin) { notify('Solo el administrador puede exportar la información operativa completa.'); return; }
    const readingValue = (measurement, patterns) => {
      const hit = (measurement.lecturas || []).find((l) => patterns.some((pattern) => `${l.codigo || ''} ${l.parametro || ''} ${l.nombreParametro || ''}`.toLowerCase().includes(pattern)));
      return hit?.valor ?? '';
    };
    const rows = [
      ...incidencias.map((r) => ({ Tipo:'Reporte ciudadano', ID:r.idIncidencia, Fecha:fmtDate(r.fechaReporte), Usuario:r.nombreReportante, Categoría:r.categoria, Título:r.titulo, Zona:r.zona, Estado:r.estado, Prioridad:r.prioridad, Equipo:r.idEquipo || '', Responsable:r.idPersonalAsignado || '', Revisión:fmtDate(r.fechaHoraRevision), Descripción:r.descripcion, Resultado:r.resultadoResolucion || '' })),
      ...equipos.map((e) => ({ Tipo:'Equipo', ID:e.idEquipo, Código:e.codigo, Nombre:e.nombre, Categoría:e.tipoEquipo, Modo:e.modoLectura, Estado:e.estado, Conexión:e.estadoConexion, Estación:e.idPunto || '', Responsable:e.idPersonalResponsable || '', Última_lectura:fmtDate(e.ultimaLecturaEn), Última_revisión:e.ultimaRevision || '', Próxima_revisión:e.proximaRevision || '', Observaciones:e.observaciones || '', Demostración:e.demo ? 'Sí' : 'No' })),
      ...personal.map((p) => ({ Tipo:'Personal', ID:p.idPersonal, Nombre:`${p.nombres} ${p.apellidos}`, Cargo:p.cargo, Área:p.area, Turno:p.turno, Correo:p.correo || '', Estado:p.estado, Demostración:p.demo ? 'Sí' : 'No' })),
      ...mantenimientos.map((m) => ({ Tipo:'Mantenimiento', ID:m.idMantenimiento, Equipo:m.idEquipo, Responsable:m.idPersonalAsignado, Programado:fmtDate(m.fechaHoraProgramada), Categoría:m.tipo, Estado:m.estado, Descripción:m.descripcion, Resultado:m.resultado || '' })),
      ...puntos.map((p) => ({ Tipo:'Punto de monitoreo', ID:p.idPunto, Nombre:p.nombrePunto, Zona:p.zona, Área:p.area, Latitud:p.latitud, Longitud:p.longitud, Estado:p.estado, Descripción:p.descripcion || '' })),
      ...mediciones.map((m) => ({ Tipo:'Medición hídrica', ID:m.idMonitoreo, Fecha:fmtDate(m.horaMuestreo), Punto:m.punto, Método:m.tipoMuestreo, Estado:m.estado, Registrado_por:m.registradoPor || '', pH:readingValue(m,['ph','hidrógeno']), Turbidez_NTU:readingValue(m,['turbidez']), Temperatura_C:readingValue(m,['temperatura']), Caudal_m3s:readingValue(m,['caudal','flujo']), Observación:m.observacion || '' })),
      ...alertasRegistradas.map((a) => ({ Tipo:'Alerta hídrica', ID:a.idAlerta, Fecha:fmtDate(a.fechaDeteccion), Punto:a.punto || '', Parámetro:a.parametro || '', Nivel:a.nivel, Valor:a.valorDetectado, Unidad:a.unidadMedida || '', Estado:a.estado, Límite_mínimo:a.umbral?.limiteMin ?? '', Límite_máximo:a.umbral?.limiteMax ?? '', Motivo:a.tipoAlerta || '' })),
    ];
    if (format === 'xlsx') exportXlsx(rows, 'operacion-alertas-ptar.xlsx');
    else if (!exportPdf(rows, 'Centro de alertas y operación — PTAR La Enlozada')) notify('Permite las ventanas emergentes para generar el PDF y elige “Guardar como PDF”.');
  };

  const tabs = isAdmin ? [
    ['reportes','Reportes recibidos'],['equipos','Equipos'],['personal','Personal y turnos'],['mantenimiento','Mantenimiento'],['archivos','Archivos públicos'],
  ] : [['enviar','Enviar observación'],['mis-reportes','Mis reportes'],['archivos','Archivos disponibles']];
  const searchPlaceholder = tab === 'personal' ? 'Buscar trabajador, cargo o área…' : tab === 'equipos' ? 'Buscar equipo por código, nombre o tipo…' : 'Buscar por título, zona, estado o descripción…';
  const exportRows = (format, rows, name) => {
    if (!isAdmin) { notify('Solo el administrador puede exportar estos registros.'); return; }
    if (format === 'xlsx') exportXlsx(rows, `${name}.xlsx`);
    else if (!exportPdf(rows, `Exportación ${name} — PTAR La Enlozada`)) notify('Permite las ventanas emergentes para generar el PDF.');
  };

  return <div className="operations-center page-stack">
    <div className="section-title"><div><span className="eyebrow">CENTRO DE ALERTAS / OPERACIÓN</span><h1>{isAdmin ? 'Seguimiento e incidencias' : 'Alertas y participación'}</h1><p>{isAdmin ? 'Desde este apartado se gestionan reportes recibidos, equipos de medición, personal y tareas de mantenimiento.' : 'Consulta las alertas y envía observaciones sobre las zonas de monitoreo. Tus reportes quedan asociados a tu cuenta.'}</p></div><button className="button button-secondary" onClick={load} disabled={loading}><Icon name="refresh-cw" size={15}/>{loading ? 'Actualizando…' : 'Actualizar'}</button></div>
    <div className="operation-tab-row" role="tablist" aria-label="Apartados de alertas">{tabs.map(([id,label]) => <button key={id} role="tab" aria-selected={tab===id} className={`operation-tab ${tab===id?'operation-tab-active':''}`} onClick={() => { setTab(id); setError(''); setQuery(''); }}>{label}{id==='reportes' && isAdmin && <span className="operation-tab-count">{incidencias.filter((r)=>!['ATENDIDA','CERRADA'].includes(r.estado)).length}</span>}</button>)}</div>
    {error && <div className="auth-error" role="alert"><Icon name="alert" size={16}/>{error}</div>}
    {loading && <div className="loading-inline"><Icon name="loader-circle" size={18}/> Consultando la base de datos…</div>}

    {tab === 'enviar' && !isAdmin && <div className="operation-two-col"><section className="panel form-panel"><div className="panel-heading"><div><h2>Enviar una observación</h2><p>Describe qué observaste y adjunta fotos o documentos si tienes evidencia.</p></div><Pill tone="info">Revisión requerida</Pill></div><form className="form-body" onSubmit={submitReport}><div className="field"><label>Tipo de observación *</label><select value={reportForm.categoria} onChange={(e)=>setReportForm({...reportForm,categoria:e.target.value})}><option>Observación ambiental</option><option>Zona posiblemente afectada</option><option>Olor o cambio visible en el agua</option><option>Daño observado en equipo</option><option>Otro</option></select></div><div className="field"><label>Título *</label><input maxLength="140" required value={reportForm.titulo} onChange={(e)=>setReportForm({...reportForm,titulo:e.target.value})} placeholder="Resume lo que quieres informar"/></div><div className="field"><label>Zona o referencia *</label><input maxLength="180" required value={reportForm.zona} onChange={(e)=>setReportForm({...reportForm,zona:e.target.value})} placeholder="Sector, punto del mapa o referencia cercana"/></div><div className="field"><label>Comentarios / descripción *</label><textarea rows="6" maxLength="4000" required value={reportForm.descripcion} onChange={(e)=>setReportForm({...reportForm,descripcion:e.target.value})} placeholder="Describe lo que observaste, fecha aproximada y cualquier detalle útil."/><small>{reportForm.descripcion.length}/4000 caracteres. Evita incluir datos personales de terceros.</small></div><div className="field"><label htmlFor="incident-evidence">Archivos de evidencia (opcional)</label><input id="incident-evidence" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.xlsx,.xls,.csv,.txt,.doc,.docx" onChange={(e)=>{const selected=Array.from(e.target.files||[]);if(selected.length>5){setError('Puedes adjuntar hasta 5 archivos por observación.');e.target.value='';return;}const tooLarge=selected.find(f=>f.size>10*1024*1024);if(tooLarge){setError(`${tooLarge.name} supera el límite de 10 MB.`);e.target.value='';return;}setError('');setReportFiles(selected);}}/><small>Hasta 5 archivos, máximo 10 MB por archivo. PDF, imágenes, Excel, CSV, TXT y Word. Los archivos no necesitan una contraseña propia; el envío sí requiere iniciar sesión.</small>{reportFiles.length>0 && <div className="selected-file-list">{reportFiles.map((file,i)=><div className="selected-file-item" key={`${file.name}-${i}`}><Icon name="file" size={15}/><span>{file.name} · {(file.size/1024/1024).toFixed(2)} MB</span><button type="button" className="button button-ghost button-small" onClick={()=>setReportFiles(old=>old.filter((_,j)=>j!==i))}>Quitar</button></div>)}</div>}</div><div className="form-footer"><span>Tu reporte quedará en estado pendiente hasta su revisión.</span><button className="button button-primary" disabled={busy} type="submit"><Icon name="send" size={16}/>{busy?'Enviando…':'Enviar observación'}</button></div></form></section><aside className="panel guidance-panel"><div className="guidance-icon"><Icon name="shield" size={20}/></div><h3>¿Qué sucede con tu reporte?</h3><div className="process-step"><span>1</span><div><strong>Registro</strong><p>Se guarda en el backend junto a tu cuenta y la fecha de envío.</p></div></div><div className="process-step"><span>2</span><div><strong>Revisión</strong><p>El equipo autorizado revisa la observación y puede solicitar seguimiento.</p></div></div><div className="process-step"><span>3</span><div><strong>Seguimiento</strong><p>Podrás consultar el estado de tus reportes en “Mis reportes”.</p></div></div></aside></div>}

    {(tab === 'mis-reportes' || tab === 'reportes') && <section className="panel"><div className="panel-heading"><div><h2>{isAdmin ? 'Bandeja de reportes recibidos' : 'Mis reportes enviados'}</h2><p>{isAdmin ? 'Todas las observaciones enviadas por cuentas registradas.' : 'Solo se muestran los reportes que enviaste desde tu cuenta.'}</p></div>{isAdmin && <div className="export-actions"><button className="button button-secondary button-small" onClick={()=>exportOperationalData('pdf')}><Icon name="file" size={14}/> PDF</button><button className="button button-secondary button-small" onClick={()=>exportOperationalData('xlsx')}><Icon name="file-spreadsheet" size={14}/> Excel</button></div>}</div><div className="user-table-controls"><label className="search-control"><Icon name="search" size={16}/><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder={searchPlaceholder}/></label></div>{filteredIncidents.length ? <div className="operation-record-list">{filteredIncidents.map((r)=><article className="operation-record" key={r.idIncidencia}><div className="operation-record-icon"><Icon name={r.categoria?.toLowerCase().includes('daño')?'wrench':'message-circle'} size={19}/></div><div className="operation-record-main"><div className="operation-record-title"><strong>{r.titulo}</strong><Pill tone={['ATENDIDA','CERRADA'].includes(r.estado)?'success':r.estado==='EN_REVISION'?'warning':'info'}>{String(r.estado).replaceAll('_',' ')}</Pill></div><p>{r.categoria} · {r.zona} · {fmtDate(r.fechaReporte)}</p><div className="operation-record-description">{r.descripcion}</div>{isAdmin && <small>Reportado por {r.nombreReportante || `Usuario #${r.idUsuarioReporta}`} · Prioridad {r.prioridad}</small>}{r.fechaHoraRevision && <small>Revisión programada: {fmtDate(r.fechaHoraRevision)}</small>}{r.resultadoResolucion && <div className="operation-resolution"><strong>Seguimiento:</strong> {r.resultadoResolucion}</div>}</div><div className="table-actions"><button className="button button-secondary button-small" onClick={()=>viewAttachments(r)}><Icon name="paperclip" size={14}/> Archivos</button>{isAdmin && <button className="button button-secondary button-small" onClick={()=>startIncident(r)}><Icon name="edit" size={14}/> Gestionar</button>}</div></article>)}</div> : <EmptyState title={loading?'Cargando reportes…':'Todavía no hay reportes'} detail={isAdmin?'Cuando un usuario envíe una observación aparecerá en esta bandeja.':'Cuando envíes una observación aparecerá aquí con su estado.'}/>}</section>}

    {tab === 'archivos' && <div className="page-stack">
      {isAdmin && <section className="panel form-panel"><div className="panel-heading"><div><h2>Publicar un documento o imagen</h2><p>Los archivos publicados estarán disponibles para usuarios registrados. Los que no publiques solo serán visibles desde administración.</p></div><Pill tone="info">Máximo 10 MB</Pill></div><form className="form-body" onSubmit={uploadPublicFile}><div className="form-grid"><div className="field"><label htmlFor="public-file-title">Título *</label><input id="public-file-title" maxLength="160" required value={publicFileForm.titulo} onChange={e=>setPublicFileForm({...publicFileForm,titulo:e.target.value})} placeholder="Ej. Resumen de monitoreo del sector"/></div><div className="field"><label htmlFor="public-file-picker">Archivo *</label><input id="public-file-picker" type="file" required accept=".pdf,.png,.jpg,.jpeg,.webp,.xlsx,.xls,.csv,.txt,.doc,.docx" onChange={e=>{const file=e.target.files?.[0]||null;if(file&&file.size>10*1024*1024){setError('El archivo supera el límite de 10 MB.');e.target.value='';setPublicFileUpload(null);return;}setError('');setPublicFileUpload(file);}}/></div><div className="field field-span-2"><label htmlFor="public-file-desc">Descripción y alcance *</label><textarea id="public-file-desc" maxLength="1000" rows="3" required value={publicFileForm.descripcion} onChange={e=>setPublicFileForm({...publicFileForm,descripcion:e.target.value})} placeholder="Indica fecha, zona, origen y qué representa el archivo. No presentes mediciones sin validar como confirmación de seguridad."/></div><div className="field field-span-2"><label className="checkbox-inline"><input type="checkbox" checked={publicFileForm.publicado} onChange={e=>setPublicFileForm({...publicFileForm,publicado:e.target.checked})}/> Publicar para descarga de usuarios</label></div></div><div className="form-footer"><span>Los documentos publicados no llevan contraseña de archivo. La aplicación controla quién puede subir o administrar contenido.</span><button type="submit" className="button button-primary" disabled={busy}><Icon name="upload" size={15}/>{busy?'Guardando…':'Guardar archivo'}</button></div></form><p className="inline-note"><Icon name="info" size={15}/> Publicar un archivo permite consultarlo y descargarlo, pero no certifica por sí solo que el agua sea segura. La fecha, el origen y la validación de la información deben constar en su descripción.</p></section>}
      <section className="panel"><div className="panel-heading"><div><h2>{isAdmin?'Biblioteca de archivos':'Archivos disponibles para descargar'}</h2><p>{isAdmin?'Gestiona la publicación y los metadatos de los documentos compartidos.':'Consulta y descarga documentos e imágenes publicados; revisa siempre la fecha y la fuente.'}</p></div><Pill tone="info">{isAdmin?adminPublicFiles.length:publicFiles.length} archivos</Pill></div>
        <p className="inline-note"><Icon name="info" size={15}/> Los documentos publicados son informativos. Su descarga no certifica por sí sola la seguridad o potabilidad del agua; verifica origen, fecha y responsable de la información.</p>
        {(isAdmin?adminPublicFiles:publicFiles).length===0 ? <EmptyState title="No hay archivos disponibles" detail={isAdmin?'Sube un documento o imagen y marca “Publicar para descarga de usuarios”.':'Cuando se publiquen documentos verificados, aparecerán aquí.'}/> : <div className="operation-record-list">{(isAdmin?adminPublicFiles:publicFiles).map(file=><article className="operation-record" key={file.idArchivo}><div className="operation-record-icon"><Icon name={String(file.tipoContenido||'').startsWith('image/')?'image':'file-text'} size={19}/></div><div className="operation-record-main"><div className="operation-record-title"><strong>{file.titulo}</strong><Pill tone={file.publicado&&file.estado==='ACTIVO'?'success':'warning'}>{file.publicado&&file.estado==='ACTIVO'?'Publicado':'Solo administración'}</Pill></div><p>{file.nombreOriginal} · {(Number(file.tamanoBytes||0)/1024/1024).toFixed(2)} MB · {fmtDate(file.fechaSubida)}</p>{file.descripcion&&<div className="operation-record-description">{file.descripcion}</div>}</div><div className="table-actions"><button className="button button-secondary button-small" onClick={()=>downloadOperationFile(file,true)}><Icon name="download" size={14}/> Descargar</button>{isAdmin&&<button className="button button-secondary button-small" onClick={()=>setEditingPublicFile({...file,descripcion:file.descripcion||'',titulo:file.titulo||''})}><Icon name="edit" size={14}/> Editar</button>}</div></article>)}</div>}
      </section>
    </div>}

    {tab === 'equipos' && <section className="panel"><div className="panel-heading"><div><h2>Equipos e instrumentos de monitoreo</h2><p>Medidores de pH, turbidímetros, caudalímetros y sensores de temperatura. El modo automático no implica conexión física activa.</p></div><div className="export-actions">{isAdmin && <><button className="button button-secondary button-small" onClick={()=>exportRows('pdf',filteredEquipment.map(e=>({Código:e.codigo,Equipo:e.nombre,Tipo:e.tipoEquipo,Modo:e.modoLectura,Estado:e.estado,Conexión:e.estadoConexion,Estación:e.idPunto||'',Responsable:e.idPersonalResponsable||'','Próxima revisión':e.proximaRevision||''})),'equipos-ptar')}><Icon name="file" size={14}/> PDF</button><button className="button button-secondary button-small" onClick={()=>exportRows('xlsx',filteredEquipment.map(e=>({Código:e.codigo,Equipo:e.nombre,Tipo:e.tipoEquipo,Modo:e.modoLectura,Estado:e.estado,Conexión:e.estadoConexion,Estación:e.idPunto||'',Responsable:e.idPersonalResponsable||'',Próxima_revision:e.proximaRevision||''})),'equipos-ptar')}><Icon name="file-spreadsheet" size={14}/> Excel</button><button className="button button-primary button-small" onClick={()=>startEquipment()}><Icon name="plus" size={14}/> Nuevo equipo</button></>}</div></div><div className="user-table-controls"><label className="search-control"><Icon name="search" size={16}/><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder={searchPlaceholder}/></label></div>{filteredEquipment.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Equipo</th><th>Tipo / modo</th><th>Estación</th><th>Conexión</th><th>Estado</th><th>Revisión</th>{isAdmin && <th>Acciones</th>}</tr></thead><tbody>{filteredEquipment.map((e)=><tr key={e.idEquipo}><td><strong>{e.nombre}</strong><small className="table-subline">{e.codigo} · {e.fabricante || 'Fabricante no indicado'} {e.modelo || ''} {e.demo && '· DEMO'}</small></td><td>{e.tipoEquipo}<small className="table-subline">{String(e.modoLectura).replaceAll('_',' ')}</small></td><td>{e.idPunto ? puntos.find(p=>p.idPunto===e.idPunto)?.nombrePunto || `Punto #${e.idPunto}` : 'Sin asignar'}</td><td><Pill tone={e.estadoConexion==='CONECTADO'?'success':e.modoLectura==='MANUAL'?'neutral':'warning'}>{String(e.estadoConexion).replaceAll('_',' ')}</Pill>{e.ultimaLecturaEn && <small className="table-subline">{fmtDate(e.ultimaLecturaEn)}</small>}</td><td><Pill tone={e.estado==='ACTIVO'?'success':'warning'}>{String(e.estado).replaceAll('_',' ')}</Pill></td><td>{e.proximaRevision || 'Sin programar'}</td>{isAdmin && <td><div className="table-actions"><button className="button button-secondary button-small" onClick={()=>startEquipment(e)}><Icon name="edit" size={14}/> Editar</button><button className="button button-ghost button-small" onClick={()=>changeEquipmentState(e)}>{e.estado==='INACTIVO'?'Activar':'Desactivar'}</button></div></td>}</tr>)}</tbody></table></div> : <EmptyState title={loading?'Cargando equipos…':'No hay equipos registrados'} detail={isAdmin?'Registra los instrumentos reales desde “Nuevo equipo”. Los equipos de ejemplo solo aparecen si se habilitan los datos de demostración.':'El catálogo se mostrará cuando el administrador registre los equipos.'}/>}</section>}

    {tab === 'personal' && isAdmin && <section className="panel"><div className="panel-heading"><div><h2>Personal operativo y turnos</h2><p>Este catálogo es independiente de las cuentas de inicio de sesión; puede asignarse personal responsable a cada equipo.</p></div><div className="export-actions"><button className="button button-secondary button-small" onClick={()=>exportRows('pdf',filteredPeople.map(p=>({Nombre:`${p.nombres} ${p.apellidos}`,Cargo:p.cargo,Área:p.area,Turno:p.turno,Correo:p.correo||'',Estado:p.estado,Demostración:p.demo?'Sí':'No'})),'personal-operativo')}><Icon name="file" size={14}/> PDF</button><button className="button button-secondary button-small" onClick={()=>exportRows('xlsx',filteredPeople.map(p=>({Nombre:`${p.nombres} ${p.apellidos}`,Cargo:p.cargo,Área:p.area,Turno:p.turno,Correo:p.correo||'',Estado:p.estado,Demostración:p.demo?'Sí':'No'})),'personal-operativo')}><Icon name="file-spreadsheet" size={14}/> Excel</button><button className="button button-primary button-small" onClick={()=>startPerson()}><Icon name="user-plus" size={14}/> Añadir trabajador</button></div></div><div className="user-table-controls"><label className="search-control"><Icon name="search" size={16}/><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder={searchPlaceholder}/></label></div>{filteredPeople.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Trabajador</th><th>Cargo</th><th>Área</th><th>Turno</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{filteredPeople.map(p=><tr key={p.idPersonal}><td><strong>{p.nombres} {p.apellidos}</strong><small className="table-subline">{p.correo || 'Sin correo'} {p.demo && '· DEMO'}</small></td><td>{p.cargo}</td><td>{p.area}</td><td>{p.turno}</td><td><Pill tone={p.estado==='ACTIVO'?'success':'warning'}>{p.estado}</Pill></td><td><div className="table-actions"><button className="button button-secondary button-small" onClick={()=>startPerson(p)}><Icon name="edit" size={14}/> Editar</button><button className="button button-ghost button-small" onClick={()=>changePersonState(p)}>{p.estado==='ACTIVO'?'Desactivar':'Activar'}</button></div></td></tr>)}</tbody></table></div> : <EmptyState title={loading?'Cargando personal…':'No hay personal operativo registrado'} detail="Agrega trabajadores y define sus turnos para poder asignarlos a equipos y mantenimientos."/>}</section>}

    {tab === 'mantenimiento' && isAdmin && <section className="panel"><div className="panel-heading"><div><h2>Programación de mantenimiento</h2><p>Asigna una fecha y hora concretas a una persona responsable y conserva el resultado de cada intervención.</p></div><div className="export-actions"><button className="button button-secondary button-small" onClick={()=>exportRows('pdf',mantenimientos.map(m=>({Equipo:equipos.find(e=>e.idEquipo===m.idEquipo)?.codigo||m.idEquipo,Responsable:personal.find(p=>p.idPersonal===m.idPersonalAsignado)?.nombres||m.idPersonalAsignado,Fecha:fmtDate(m.fechaHoraProgramada),Tipo:m.tipo,Estado:m.estado,Descripción:m.descripcion,Resultado:m.resultado||''})),'mantenimientos')}><Icon name="file" size={14}/> PDF</button><button className="button button-secondary button-small" onClick={()=>exportRows('xlsx',mantenimientos.map(m=>({Equipo:equipos.find(e=>e.idEquipo===m.idEquipo)?.codigo||m.idEquipo,Responsable:personal.find(p=>p.idPersonal===m.idPersonalAsignado)?.nombres||m.idPersonalAsignado,Fecha:fmtDate(m.fechaHoraProgramada),Tipo:m.tipo,Estado:m.estado,Descripción:m.descripcion,Resultado:m.resultado||''})),'mantenimientos')}><Icon name="file-spreadsheet" size={14}/> Excel</button><button className="button button-primary button-small" onClick={()=>setMaintenanceModal(true)}><Icon name="calendar" size={14}/> Programar tarea</button></div></div>{mantenimientos.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Equipo</th><th>Responsable</th><th>Fecha y hora</th><th>Tipo</th><th>Descripción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{mantenimientos.map(m=><tr key={m.idMantenimiento}><td>{equipos.find(e=>e.idEquipo===m.idEquipo)?.codigo || `Equipo #${m.idEquipo}`}</td><td>{personal.find(p=>p.idPersonal===m.idPersonalAsignado) ? `${personal.find(p=>p.idPersonal===m.idPersonalAsignado).nombres} ${personal.find(p=>p.idPersonal===m.idPersonalAsignado).apellidos}` : `Personal #${m.idPersonalAsignado}`}</td><td>{fmtDate(m.fechaHoraProgramada)}</td><td>{m.tipo}</td><td>{m.descripcion}</td><td><Pill tone={m.estado==='COMPLETADO'?'success':m.estado==='EN_PROCESO'?'warning':'info'}>{String(m.estado).replaceAll('_',' ')}</Pill></td><td><div className="table-actions"><button disabled={m.estado==='EN_PROCESO'||m.estado==='COMPLETADO'||m.estado==='CANCELADO'} className="button button-secondary button-small" onClick={()=>setMaintenanceState(m,'EN_PROCESO')}>Iniciar</button><button disabled={m.estado==='COMPLETADO'||m.estado==='CANCELADO'} className="button button-ghost button-small" onClick={()=>setMaintenanceState(m,'COMPLETADO')}>Completar</button></div></td></tr>)}</tbody></table></div> : <EmptyState title="No hay mantenimientos programados" detail="Programa revisiones preventivas o tareas de reparación desde este apartado."/>}</section>}

    {equipmentModal !== null && isAdmin && <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setEquipmentModal(null);}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="equipment-title"><div className="modal-heading"><div><span className="eyebrow">CENTRO DE ALERTAS / EQUIPOS</span><h2 id="equipment-title">{equipmentModal?'Editar equipo':'Nuevo equipo'}</h2><p>Una lectura automática solo se mostrará conectada si existe integración real.</p></div><button className="icon-button" onClick={()=>setEquipmentModal(null)} aria-label="Cerrar"><Icon name="close"/></button></div><form className="form-body" onSubmit={saveEquipment}><div className="form-grid"><div className="field"><label>Código *</label><input maxLength="35" required value={equipmentForm.codigo} onChange={e=>setEquipmentForm({...equipmentForm,codigo:e.target.value})} placeholder="PH-001"/></div><div className="field"><label>Nombre *</label><input maxLength="130" required value={equipmentForm.nombre} onChange={e=>setEquipmentForm({...equipmentForm,nombre:e.target.value})} placeholder="Medidor de pH en línea"/></div><div className="field"><label>Tipo de equipo *</label><select value={equipmentForm.tipoEquipo} onChange={e=>setEquipmentForm({...equipmentForm,tipoEquipo:e.target.value})}><option>Medidor de pH</option><option>Turbidímetro</option><option>Caudalímetro</option><option>Sensor de temperatura</option><option>Estación multiparámetro</option><option>Otro instrumento</option></select></div><div className="field"><label>Modo de lectura *</label><select value={equipmentForm.modoLectura} onChange={e=>setEquipmentForm({...equipmentForm,modoLectura:e.target.value})}><option value="MANUAL">Manual</option><option value="SEMIAUTOMATICO">Semiautomático</option><option value="AUTOMATICO">Automático</option></select></div><div className="field"><label>Fabricante</label><input maxLength="100" value={equipmentForm.fabricante} onChange={e=>setEquipmentForm({...equipmentForm,fabricante:e.target.value})}/></div><div className="field"><label>Modelo</label><input maxLength="100" value={equipmentForm.modelo} onChange={e=>setEquipmentForm({...equipmentForm,modelo:e.target.value})}/></div><div className="field"><label>Estación</label><select value={equipmentForm.idPunto} onChange={e=>setEquipmentForm({...equipmentForm,idPunto:e.target.value})}><option value="">Sin asignar</option>{puntos.map(p=><option key={p.idPunto} value={p.idPunto}>{p.nombrePunto}</option>)}</select></div><div className="field"><label>Responsable</label><select value={equipmentForm.idPersonalResponsable} onChange={e=>setEquipmentForm({...equipmentForm,idPersonalResponsable:e.target.value})}><option value="">Sin asignar</option>{personal.filter(p=>p.estado==='ACTIVO').map(p=><option key={p.idPersonal} value={p.idPersonal}>{p.nombres} {p.apellidos} · {p.cargo}</option>)}</select></div><div className="field"><label>Estado del equipo</label><select value={equipmentForm.estado} onChange={e=>setEquipmentForm({...equipmentForm,estado:e.target.value})}><option value="ACTIVO">Activo</option><option value="EN_MANTENIMIENTO">En mantenimiento</option><option value="DANADO">Dañado</option><option value="INACTIVO">Inactivo</option></select></div><div className="field"><label>Conectividad</label><select value={equipmentForm.estadoConexion} onChange={e=>setEquipmentForm({...equipmentForm,estadoConexion:e.target.value})}><option value="NO_APLICA">No aplica</option><option value="CONECTADO">Conectado</option><option value="SIN_CONEXION">Sin conexión</option><option value="ERROR">Error</option></select></div><div className="field"><label>Última revisión</label><input type="date" value={equipmentForm.ultimaRevision} onChange={e=>setEquipmentForm({...equipmentForm,ultimaRevision:e.target.value})}/></div><div className="field"><label>Próxima revisión</label><input type="date" value={equipmentForm.proximaRevision} onChange={e=>setEquipmentForm({...equipmentForm,proximaRevision:e.target.value})}/></div><div className="field field-span-2"><label>Observaciones</label><textarea rows="3" maxLength="1000" value={equipmentForm.observaciones} onChange={e=>setEquipmentForm({...equipmentForm,observaciones:e.target.value})}/></div></div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setEquipmentModal(null)}>Cancelar</button><button type="submit" disabled={busy} className="button button-primary">{busy?'Guardando…':'Guardar equipo'} <Icon name="check" size={15}/></button></div></form></section></div>}

    {personModal !== null && isAdmin && <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setPersonModal(null);}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="person-title"><div className="modal-heading"><div><span className="eyebrow">CENTRO DE ALERTAS / PERSONAL</span><h2 id="person-title">{personModal?'Editar trabajador':'Añadir trabajador'}</h2><p>Los datos de personal operativo no crean automáticamente una cuenta de inicio de sesión.</p></div><button className="icon-button" onClick={()=>setPersonModal(null)} aria-label="Cerrar"><Icon name="close"/></button></div><form className="form-body" onSubmit={savePerson}><div className="form-grid"><div className="field"><label>Nombres *</label><input maxLength="90" required value={personForm.nombres} onChange={e=>setPersonForm({...personForm,nombres:e.target.value})}/></div><div className="field"><label>Apellidos *</label><input maxLength="90" required value={personForm.apellidos} onChange={e=>setPersonForm({...personForm,apellidos:e.target.value})}/></div><div className="field"><label>Cargo *</label><input maxLength="100" required value={personForm.cargo} onChange={e=>setPersonForm({...personForm,cargo:e.target.value})}/></div><div className="field"><label>Área *</label><input maxLength="100" required value={personForm.area} onChange={e=>setPersonForm({...personForm,area:e.target.value})}/></div><div className="field"><label>Turno u horario *</label><select value={personForm.turno} onChange={e=>setPersonForm({...personForm,turno:e.target.value})}><option>07:00–15:00</option><option>15:00–23:00</option><option>23:00–07:00</option><option>08:00–17:00</option><option>Horario administrativo</option><option>Rotativo</option></select></div><div className="field"><label>Estado</label><select value={personForm.estado} onChange={e=>setPersonForm({...personForm,estado:e.target.value})}><option value="ACTIVO">Activo</option><option value="INACTIVO">Inactivo</option></select></div><div className="field"><label>Correo (opcional)</label><input type="email" maxLength="120" value={personForm.correo} onChange={e=>setPersonForm({...personForm,correo:e.target.value})}/></div><div className="field"><label>Teléfono (opcional)</label><input maxLength="25" value={personForm.telefono} onChange={e=>setPersonForm({...personForm,telefono:e.target.value})}/></div></div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setPersonModal(null)}>Cancelar</button><button type="submit" disabled={busy} className="button button-primary">{busy?'Guardando…':'Guardar trabajador'}</button></div></form></section></div>}

    {maintenanceModal && isAdmin && <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setMaintenanceModal(false);}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="maint-title"><div className="modal-heading"><div><span className="eyebrow">CENTRO DE ALERTAS / MANTENIMIENTO</span><h2 id="maint-title">Programar revisión</h2><p>Elige una fecha y hora futuras y un responsable activo.</p></div><button className="icon-button" onClick={()=>setMaintenanceModal(false)} aria-label="Cerrar"><Icon name="close"/></button></div><form className="form-body" onSubmit={saveMaintenance}><div className="form-grid"><div className="field"><label>Equipo *</label><select required value={maintenanceForm.idEquipo} onChange={e=>setMaintenanceForm({...maintenanceForm,idEquipo:e.target.value})}><option value="">Seleccionar equipo</option>{equipos.filter(e=>e.estado!=='INACTIVO').map(e=><option key={e.idEquipo} value={e.idEquipo}>{e.codigo} · {e.nombre}</option>)}</select></div><div className="field"><label>Responsable *</label><select required value={maintenanceForm.idPersonalAsignado} onChange={e=>setMaintenanceForm({...maintenanceForm,idPersonalAsignado:e.target.value})}><option value="">Seleccionar trabajador</option>{personal.filter(p=>p.estado==='ACTIVO').map(p=><option key={p.idPersonal} value={p.idPersonal}>{p.nombres} {p.apellidos} · {p.turno}</option>)}</select></div><div className="field"><label>Fecha y hora *</label><input required type="datetime-local" value={maintenanceForm.fechaHoraProgramada} onChange={e=>setMaintenanceForm({...maintenanceForm,fechaHoraProgramada:e.target.value})}/></div><div className="field"><label>Tipo *</label><select value={maintenanceForm.tipo} onChange={e=>setMaintenanceForm({...maintenanceForm,tipo:e.target.value})}><option>Preventivo</option><option>Correctivo</option><option>Calibración</option><option>Inspección por daño</option></select></div><div className="field field-span-2"><label>Trabajo por realizar *</label><textarea rows="4" maxLength="1500" required value={maintenanceForm.descripcion} onChange={e=>setMaintenanceForm({...maintenanceForm,descripcion:e.target.value})} placeholder="Ej. inspeccionar carcasa, verificar lectura y revisar conexión."/></div></div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setMaintenanceModal(false)}>Cancelar</button><button type="submit" disabled={busy} className="button button-primary">{busy?'Guardando…':'Programar mantenimiento'}</button></div></form></section></div>}

    {attachmentTarget && <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setAttachmentTarget(null);}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="attachment-title"><div className="modal-heading"><div><span className="eyebrow">CENTRO DE ALERTAS / ARCHIVOS</span><h2 id="attachment-title">Archivos del reporte #{attachmentTarget.idIncidencia}</h2><p>{attachmentTarget.titulo} · {attachmentTarget.zona}</p></div><button className="icon-button" onClick={()=>setAttachmentTarget(null)} aria-label="Cerrar"><Icon name="close"/></button></div><div className="form-body">{incidentAttachments.length===0?<EmptyState title="No hay archivos adjuntos" detail="Este reporte no tiene evidencias cargadas."/>:<div className="operation-record-list">{incidentAttachments.map(file=><article className="operation-record" key={file.idArchivo}><div className="operation-record-icon"><Icon name={String(file.tipoContenido||'').startsWith('image/')?'image':'file-text'} size={18}/></div><div className="operation-record-main"><strong>{file.nombreOriginal}</strong><p>{(Number(file.tamanoBytes||0)/1024/1024).toFixed(2)} MB · {fmtDate(file.fechaSubida)}</p>{file.descripcion&&<div className="operation-record-description">{file.descripcion}</div>}<Pill tone={file.publicado?'success':'neutral'}>{file.publicado?'Publicado para descarga':'Privado / revisión'}</Pill></div><div className="table-actions"><button className="button button-secondary button-small" onClick={()=>downloadOperationFile(file,false)}><Icon name="download" size={14}/> Descargar</button>{isAdmin&&<button className="button button-ghost button-small" onClick={()=>publishIncidentAttachment(file)}>{file.publicado?'Retirar publicación':'Publicar'}</button>}</div></article>)}</div>}<div className="modal-actions"><button className="button button-secondary" type="button" onClick={()=>setAttachmentTarget(null)}>Cerrar</button></div></div></section></div>}

    {editingPublicFile && isAdmin && <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setEditingPublicFile(null);}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="public-edit-title"><div className="modal-heading"><div><span className="eyebrow">BIBLIOTECA PÚBLICA</span><h2 id="public-edit-title">Editar archivo</h2><p>Modifica los metadatos o retira el documento de la publicación.</p></div><button className="icon-button" onClick={()=>setEditingPublicFile(null)} aria-label="Cerrar"><Icon name="close"/></button></div><form className="form-body" onSubmit={e=>{e.preventDefault();savePublicFileMetadata(editingPublicFile,{titulo:editingPublicFile.titulo,descripcion:editingPublicFile.descripcion,publicado:editingPublicFile.publicado,estado:editingPublicFile.estado});}}><div className="field"><label>Título *</label><input required maxLength="160" value={editingPublicFile.titulo} onChange={e=>setEditingPublicFile({...editingPublicFile,titulo:e.target.value})}/></div><div className="field"><label>Descripción *</label><textarea required rows="4" maxLength="1000" value={editingPublicFile.descripcion} onChange={e=>setEditingPublicFile({...editingPublicFile,descripcion:e.target.value})}/></div><div className="form-grid"><div className="field"><label>Publicación</label><select value={String(editingPublicFile.publicado)} onChange={e=>setEditingPublicFile({...editingPublicFile,publicado:e.target.value==='true'})}><option value="true">Publicado</option><option value="false">Privado</option></select></div><div className="field"><label>Estado</label><select value={editingPublicFile.estado} onChange={e=>setEditingPublicFile({...editingPublicFile,estado:e.target.value})}><option value="ACTIVO">Activo</option><option value="INACTIVO">Inactivo</option></select></div></div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setEditingPublicFile(null)}>Cancelar</button><button type="submit" disabled={busy} className="button button-primary">Guardar cambios</button></div></form></section></div>}

    {selectedIncident && isAdmin && <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setSelectedIncident(null);}}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="incident-title"><div className="modal-heading"><div><span className="eyebrow">REVISIÓN DE INCIDENCIA</span><h2 id="incident-title">Gestionar reporte #{selectedIncident.idIncidencia}</h2><p>{selectedIncident.titulo} · {selectedIncident.zona}</p></div><button className="icon-button" onClick={()=>setSelectedIncident(null)} aria-label="Cerrar"><Icon name="close"/></button></div><form className="form-body" onSubmit={manageIncident}><div className="form-grid"><div className="field"><label>Tipo de reporte</label><input maxLength="50" value={incidentForm.categoria} onChange={e=>setIncidentForm({...incidentForm,categoria:e.target.value})}/></div><div className="field"><label>Título</label><input maxLength="140" value={incidentForm.titulo} onChange={e=>setIncidentForm({...incidentForm,titulo:e.target.value})}/></div><div className="field field-span-2"><label>Zona o referencia</label><input maxLength="180" value={incidentForm.zona} onChange={e=>setIncidentForm({...incidentForm,zona:e.target.value})}/></div><div className="field field-span-2"><label>Descripción corregida</label><textarea rows="4" maxLength="4000" value={incidentForm.descripcion} onChange={e=>setIncidentForm({...incidentForm,descripcion:e.target.value})}/></div><div className="field"><label>Estado</label><select value={incidentForm.estado} onChange={e=>setIncidentForm({...incidentForm,estado:e.target.value})}><option value="PENDIENTE">Pendiente</option><option value="EN_REVISION">En revisión</option><option value="ASIGNADA">Asignada</option><option value="ATENDIDA">Atendida</option><option value="CERRADA">Cerrada</option><option value="REQUIERE_INFORMACION">Requiere información</option></select></div><div className="field"><label>Prioridad</label><select value={incidentForm.prioridad} onChange={e=>setIncidentForm({...incidentForm,prioridad:e.target.value})}><option value="BAJA">Baja</option><option value="MEDIA">Media</option><option value="ALTA">Alta</option><option value="CRITICA">Crítica</option></select></div><div className="field"><label>Equipo afectado</label><select value={incidentForm.idEquipo} onChange={e=>setIncidentForm({...incidentForm,idEquipo:e.target.value})}><option value="">No asignado</option>{equipos.map(e=><option key={e.idEquipo} value={e.idEquipo}>{e.codigo} · {e.nombre}</option>)}</select></div><div className="field"><label>Responsable autorizado</label><select value={incidentForm.idPersonalAsignado} onChange={e=>setIncidentForm({...incidentForm,idPersonalAsignado:e.target.value})}><option value="">No asignado</option>{personal.filter(p=>p.estado==='ACTIVO').map(p=><option key={p.idPersonal} value={p.idPersonal}>{p.nombres} {p.apellidos} · {p.cargo}</option>)}</select></div><div className="field field-span-2"><label>Fecha y hora de revisión</label><input type="datetime-local" value={incidentForm.fechaHoraRevision} onChange={e=>setIncidentForm({...incidentForm,fechaHoraRevision:e.target.value})}/></div><div className="field field-span-2"><label>Notas de seguimiento / resolución</label><textarea rows="4" maxLength="2000" value={incidentForm.resultadoResolucion} onChange={e=>setIncidentForm({...incidentForm,resultadoResolucion:e.target.value})} placeholder="Acción acordada, persona notificada y resultado de la revisión."/></div></div><div className="modal-actions"><button type="button" className="button button-secondary" onClick={()=>setSelectedIncident(null)}>Cancelar</button><button type="submit" disabled={busy} className="button button-primary">{busy?'Guardando…':'Guardar seguimiento'}</button></div></form></section></div>}
  </div>;
}
